cyber_blog_platform.styles:

:root {
    --bg-deep: #070913;
    --bg-surface: rgba(15, 22, 38, 0.85);
    --neon-cyan: #00f0ff;
    --neon-pink: #ff007f;
    --neon-purple: #9d00ff;
    --text-main: #f0f6fc;
    --text-muted: #8b949e;
    --border-glow: rgba(0, 240, 255, 0.25);
    --card-border: rgba(255, 255, 255, 0.08);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

body {
    background-color: var(--bg-deep);
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 40px 20px;
    overflow-x: hidden;
    position: relative;
}

body::before {
    content: '';
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 800px;
    height: 400px;
    background: radial-gradient(circle, rgba(0,240,255,0.12) 0%, rgba(157,0,255,0.06) 50%, transparent 100%);
    z-index: -1;
    filter: blur(80px);
}

.blog-container {
    width: 100%;
    max-width: 900px;
    display: flex;
    flex-direction: column;
    gap: 28px;
    z-index: 2;
}

.site-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bg-surface);
    padding: 20px 30px;
    border-radius: 16px;
    border: 1px solid var(--border-glow);
    box-shadow: 0 0 25px rgba(0, 240, 255, 0.1);
    backdrop-filter: blur(16px);
}

.brand-wrapper {
    display: flex;
    align-items: center;
    gap: 16px;
}

.site-icon {
    width: 48px;
    height: 48px;
    object-fit: contain;
    filter: drop-shadow(0 0 10px var(--neon-cyan));
    animation: icon-glow 3s infinite ease-in-out;
}

@keyframes icon-glow {
    0%, 100% { filter: drop-shadow(0 0 8px var(--neon-cyan)); transform: scale(1); }
    50% { filter: drop-shadow(0 0 18px var(--neon-cyan)); transform: scale(1.04); }
}

.brand-title h1 {
    font-size: 1.4rem;
    font-weight: 800;
    letter-spacing: 1.2px;
    background: linear-gradient(90deg, #fff, var(--neon-cyan));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.brand-title span {
    font-size: 0.75rem;
    color: var(--text-muted);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.system-status {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.85rem;
    color: var(--neon-cyan);
    background: rgba(0, 240, 255, 0.08);
    padding: 6px 14px;
    border-radius: 20px;
    border: 1px solid rgba(0, 240, 255, 0.2);
}

.status-dot {
    width: 8px;
    height: 8px;
    background-color: var(--neon-cyan);
    border-radius: 50%;
    box-shadow: 0 0 8px var(--neon-cyan);
    animation: pulse-dot 1.5s infinite;
}

@keyframes pulse-dot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.4; }
}

.blog-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 22px;
}

/* Blog Post Card (Başlık, İkon ve Blurlu İçerik) */
.blog-post {
    background: var(--bg-surface);
    border: 1px solid var(--card-border);
    border-radius: 14px;
    padding: 24px;
    backdrop-filter: blur(12px);
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.blog-post::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    background: linear-gradient(to bottom, var(--neon-cyan), var(--neon-pink));
}

.post-header {
    display: flex;
    align-items: center;
    gap: 14px;
}

.post-mini-icon {
    width: 32px;
    height: 32px;
    object-fit: contain;
    filter: drop-shadow(0 0 6px var(--neon-cyan));
}

.post-meta-title {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex-grow: 1;
}

.blog-post h2 {
    font-size: 1.15rem;
    color: #fff;
    margin: 0;
}

.post-date {
    font-size: 0.75rem;
    color: var(--text-muted);
    letter-spacing: 0.5px;
}

/* Blurlu İçerik Alanı */
.post-content-wrapper {
    position: relative;
    max-height: 44px;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.post-content-wrapper.expanded {
    max-height: 400px;
}

.blur-content {
    filter: blur(6px);
    user-select: none;
    opacity: 0.4;
    transition: filter 0.4s ease, opacity 0.4s ease;
    color: var(--text-muted);
    font-size: 0.95rem;
    line-height: 1.6;
}

.post-content-wrapper.expanded .blur-content {
    filter: blur(0px);
    opacity: 1;
    user-select: text;
}

/* See More Butonu */
.see-more-btn {
    background: rgba(0, 240, 255, 0.08);
    border: 1px solid rgba(0, 240, 255, 0.2);
    color: var(--neon-cyan);
    padding: 8px 18px;
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    align-self: flex-start;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 6px;
}

.see-more-btn:hover {
    background: var(--neon-cyan);
    color: #000;
    box-shadow: 0 0 15px var(--neon-cyan);
}

/* Tıklama Baloncuk Efekti */
.click-bubble {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    transform: translate(-50%, -50%);
    animation: bubble-burst 0.6s cubic-bezier(0.25, 1, 0.5, 1) forwards;
    z-index: 9999;
}

@keyframes bubble-burst {
    0% {
        width: 12px;
        height: 12px;
        opacity: 1;
        box-shadow: 0 0 10px var(--neon-cyan), inset 0 0 5px var(--neon-cyan);
        border: 2px solid var(--neon-cyan);
    }
    100% {
        width: 90px;
        height: 90px;
        opacity: 0;
        transform: translate(-50%, -50%) scale(1.25);
        box-shadow: 0 0 30px var(--neon-pink), inset 0 0 15px var(--neon-pink);
        border: 1px solid var(--neon-pink);
    }
}

cyber_blog_platform.script:

// See More / See Less toggle function for blog posts
function togglePost(wrapperId, btn) {
    const wrapper = document.getElementById(wrapperId);
    wrapper.classList.toggle('expanded');

    if (wrapper.classList.contains('expanded')) {
        btn.textContent = 'See Less';
    } else {
        btn.textContent = 'See More';
    }
}

// Global click bubble effect listener
document.addEventListener('click', function(e) {
    const bubble = document.createElement('div');
    bubble.classList.add('click-bubble');
    bubble.style.left = e.pageX + 'px';
    bubble.style.top = e.pageY + 'px';
    document.body.appendChild(bubble);

    setTimeout(() => {
        bubble.remove();
    }, 600);
});
